      ('sandisk-ultra-dual-drive-luxe-usb-c', '256GB', 83, 'USB Flash Drives', 'SanDisk 256GB Flash Ultra Luxe Dual Drive', 'Not specified', '256GB', NULL),
      ('sandisk-ultra-dual-drive-luxe-usb-c', '1TB', 80, 'USB Flash Drives', 'SanDisk 1TB Flash Ultra Luxe Dual Drive', 'Not specified', '1TB', NULL),
      ('sandisk-cruzer-blade-cz50', '16GB', 84, 'USB Flash Drives', 'SanDisk 16GB Flash Cruzer Blade CZ50', 'Not specified', '16GB', 'No selling price in the stock list — variant switched off until a price is set.'),
      ('sandisk-cruzer-blade-cz50', '128GB', 85, 'USB Flash Drives', 'SanDisk 128GB Flash Cruzer Blade CZ50', 'Not specified', '128GB', NULL),
      ('sandisk-cruzer-glide-cz600', '16GB', 86, 'USB Flash Drives', 'SanDisk 16GB Flash Glide USB 3.0 CZ600', 'Not specified', '16GB', NULL),
      ('sandisk-cruzer-glide-cz600', '32GB', 87, 'USB Flash Drives', 'SanDisk 32GB Flash Glide USB 3.0 CZ600', 'Not specified', '32GB', NULL),
      ('sandisk-cruzer-glide-cz600', '128GB', 88, 'USB Flash Drives', 'SanDisk 128GB Flash Glide USB 3.0 CZ600', 'Not specified', '128GB', NULL),
      ('sandisk-cruzer-glide-cz600', '256GB', 89, 'USB Flash Drives', 'SanDisk 256GB Flash Glide USB 3.0 CZ600', 'Not specified', '256GB', NULL),
      ('tp-link-tl-wn823n-mini-wireless-usb-adapter', 'Standard', 90, 'Network Adapter', 'Tplink W/L Mini USB Adaptor 300Mbps Wn823n', 'Not specified', NULL, NULL),
      ('kingston-16gb-ddr5-5600-desktop-ram', 'Standard', 91, 'Internal Storage', 'Kingston RAM 16GB DDR5 Desktop 5600', 'Not specified', NULL, 'Final selling range in the stock list: 52,000-55,000 (shop price set to the lower figure).')
    ) AS d(slug, name, source_row, source_category, source_description, colour, other_variant, price_note)
    JOIN public.products p ON p.slug = d.slug
    JOIN public.product_variants v ON v.product_id = p.id AND lower(v.name) = lower(d.name)
  ON CONFLICT (variant_id) DO NOTHING;

  INSERT INTO public.app_config (name, value) VALUES (c_marker, to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SSOF'))
  ON CONFLICT (name) DO NOTHING;

  -- ── 2g. Self-verification: any failure rolls the whole seed back ────────────────────────────
  SELECT count(*) INTO v_n FROM public.products WHERE slug = ANY (c_slugs);
  IF v_n <> 59 THEN RAISE EXCEPTION '34_seed_inventory: expected 59 products, found %', v_n; END IF;

  SELECT count(*) INTO v_n
    FROM public.product_variants v JOIN public.products p ON p.id = v.product_id
   WHERE p.slug = ANY (c_slugs);
  IF v_n <> 86 THEN RAISE EXCEPTION '34_seed_inventory: expected 86 variants, found %', v_n; END IF;

  SELECT count(*) INTO v_n
    FROM public.product_variants v JOIN public.products p ON p.id = v.product_id
   WHERE p.slug = ANY (c_slugs) AND v.is_active AND v.price > 0;
  IF v_n <> 85 THEN RAISE EXCEPTION '34_seed_inventory: expected 85 priced active variants, found %', v_n; END IF;

  SELECT string_agg(p.slug, ', ') INTO v_bad
    FROM public.products p
   WHERE p.slug = ANY (c_slugs)
     AND (NOT p.is_active OR p.variant_count < 1 OR p.default_variant_id IS NULL OR p.price <= 0 OR p.category_id IS NULL);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '34_seed_inventory: products not visible/purchasable: %', v_bad; END IF;

  SELECT count(*), COALESCE(sum(i.stock_level), 0) INTO v_n, v_sum
    FROM public.inventory i JOIN public.products p ON p.id = i.product_id
   WHERE p.slug = ANY (c_slugs);
  IF v_n <> 86 OR v_sum <> 268 THEN
    RAISE EXCEPTION '34_seed_inventory: expected 86 stock rows totalling 268, found % totalling %', v_n, v_sum;
  END IF;

  SELECT count(*) INTO v_n
    FROM public.variant_sourcing s JOIN public.product_variants v ON v.id = s.variant_id
    JOIN public.products p ON p.id = v.product_id
   WHERE p.slug = ANY (c_slugs);
  IF v_n <> 86 THEN RAISE EXCEPTION '34_seed_inventory: expected 86 variant_sourcing rows, found %', v_n; END IF;

  SELECT count(*) INTO v_n FROM public.products WHERE slug = ANY (c_demo) AND is_active;
  IF v_n <> 0 THEN RAISE EXCEPTION '34_seed_inventory: % demo products still active', v_n; END IF;
  SELECT count(*) INTO v_n FROM public.collections WHERE id = ANY (c_demo_collections) AND is_active;
  IF v_n <> 0 THEN RAISE EXCEPTION '34_seed_inventory: % demo collections still active', v_n; END IF;

  RAISE NOTICE '34_seed_inventory: 59 products, 86 variants, 86 stock rows (268 units); demo catalogue + collections hidden';
END $seed$;

